function demoMain(idx,label){
  var traces=[["main>init","init>load","main>run"],["a>b","b>c","a>c"],["x>y","y>z"]];
  var t=traces[idx%traces.length];
  var nodes={};t.forEach(function(e){var p=e.split(">");nodes[p[0]]=1;nodes[p[1]]=1;});
  return "["+label+"] call graph: "+t.join(", ")+" ("+Object.keys(nodes).length+" nodes)";
}

